# The hash to look up: set the `hash` input to where it comes from
value = str(inputs['hash'] or '').strip().lower()
if not re_fullmatch('[0-9a-f]{32}|[0-9a-f]{40}|[0-9a-f]{64}', value):
    fail(f'Not an MD5, SHA-1 or SHA-256 hash: {value[:80]}')
result = {'collection': 'files', 'id': value}

# Detection counts and verdict of the VirusTotal answer
THRESHOLD = 3
response = inputs['response'] if is_dict(inputs['response']) else {}
body = response.get('body') if is_dict(response.get('body')) else {}
item = body.get('data') if is_dict(body.get('data')) else {}
attributes = item.get('attributes') if is_dict(item.get('attributes')) else {}
stats = attributes.get('last_analysis_stats') if is_dict(attributes.get('last_analysis_stats')) else {}
found = response.get('status_code') == 200 and bool(attributes)
malicious = int(stats.get('malicious') or 0)
suspicious = int(stats.get('suspicious') or 0)
if not found:
    verdict = 'unknown'
elif malicious >= THRESHOLD:
    verdict = 'malicious'
elif malicious > 0 or suspicious > 0:
    verdict = 'suspicious'
else:
    verdict = 'clean'
result = {
    'found': found,
    'verdict': verdict,
    'malicious': malicious,
    'suspicious': suspicious,
    'engines': sum([int(count) for count in stats.values() if is_number(count)]),
    'name': attributes.get('meaningful_name'),
    'type': attributes.get('type_description'),
    'threat_label': (attributes.get('popular_threat_classification') or {}).get('suggested_threat_label'),
    'link': f"https://www.virustotal.com/gui/file/{item.get('id')}" if found else None,
}
